def drivers_from_deliveries(apps, schema_editor):
    """Deliveries are cash only from now on, and every driver used so far goes on the drivers list."""
    Delivery = apps.get_model("invoices", "Delivery")
    Driver = apps.get_model("invoices", "Driver")
    Delivery.objects.exclude(pay="driver").update(pay="driver")
    found = {}
    for d in Delivery.objects.order_by("id"):
        key = " ".join(d.driver_name.lower().split())
        if not key:
            continue
        drv = found.get(key)
        if drv is None:
            drv = Driver.objects.create(name=d.driver_name, phone=d.driver_phone, car_reg=d.car_reg,
                                        car_make=d.car_make, car_colour=d.car_colour, issued=d.date)
            found[key] = drv
        else:
            drv.phone = d.driver_phone or drv.phone
            drv.car_reg, drv.car_make, drv.car_colour = d.car_reg, d.car_make, d.car_colour
            drv.save()
        d.driver = drv
        d.save(update_fields=["driver"])


